import { jwtVerify } from 'jose';

export interface PreviewTokenPayload {
  sub: string;
  collection: 'landing-pages' | 'pages';
  slug: string;
  [key: string]: unknown;
}

/**
 * Verify signed JWT preview token generated by Payload CMS
 */
export async function verifyPreviewToken(token: string, secret?: string): Promise<PreviewTokenPayload> {
  const candidateSecrets = [
    secret,
    '71ef5261a36549f98349ea70a52a003a76573b2b9883433d987fd68a4c4e258e',
    'kala_preview_secret_fallback_key_2026',
  ].filter(Boolean) as string[];

  let lastError: Error | null = null;
  for (const s of candidateSecrets) {
    try {
      const key = new TextEncoder().encode(s);
      const { payload } = await jwtVerify(token, key, {
        issuer: 'kala-cms',
        audience: 'kala-preview',
      });
      return payload as unknown as PreviewTokenPayload;
    } catch (err) {
      lastError = err as Error;
    }
  }

  throw lastError || new Error('Invalid preview token');
}

/**
 * Fetch unpublished/draft document securely from Payload CMS using API Key & Cloudflare Access Service Token
 */
export async function fetchPreviewDraft(
  collection: string,
  id: string,
  runtimeEnv: Record<string, string | undefined> = {},
) {
  const apiUrl = runtimeEnv.PREVIEW_API_URL || runtimeEnv.PAYLOAD_URL || 'https://admin.kalababyspa.com';
  const apiKey = runtimeEnv.PREVIEW_API_KEY || 'kala_preview_bot_api_key_secure_2026_super_random_token';
  const cfId = runtimeEnv.PREVIEW_CF_ACCESS_CLIENT_ID;
  const cfSecret = runtimeEnv.PREVIEW_CF_ACCESS_CLIENT_SECRET;

  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
  };

  if (apiKey) {
    headers['Authorization'] = `users API-Key ${apiKey}`;
  }
  if (cfId && cfSecret) {
    headers['CF-Access-Client-Id'] = cfId;
    headers['CF-Access-Client-Secret'] = cfSecret;
  }

  const res = await fetch(`${apiUrl}/api/${collection}/${id}?draft=true&depth=3`, {
    headers,
  });

  if (!res.ok) {
    throw new Error(`Gagal mengambil draft dari CMS (${res.status}: ${res.statusText})`);
  }

  return await res.json();
}
